-- The tables of the project, for Oracle 12c or later.
-- Generated by ElastiCORE from the model, in the column types that database's Hibernate dialect would
-- choose. Run it with spring.sql.init.schema-locations on an empty database.

CREATE SEQUENCE revinfo_seq START WITH 1 INCREMENT BY 50;

CREATE TABLE bill_receipt (
    receipt_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    order_id VARCHAR2(36 CHAR) NOT NULL,
    amount NUMBER(14,2) NOT NULL,
    PRIMARY KEY (receipt_id)
);

CREATE TABLE brd_bookmark (
    bookmark_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    label VARCHAR2(50 CHAR),
    post_post_id NUMBER(19),
    PRIMARY KEY (bookmark_id)
);

CREATE TABLE brd_comment (
    comment_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    text VARCHAR2(200 CHAR) NOT NULL,
    post_post_id NUMBER(19) NOT NULL,
    parent_comment_id NUMBER(19),
    PRIMARY KEY (comment_id)
);

CREATE TABLE brd_post (
    post_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    title VARCHAR2(100 CHAR) NOT NULL,
    PRIMARY KEY (post_id)
);

CREATE TABLE brd_report (
    report_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    reason VARCHAR2(100 CHAR),
    post_post_id NUMBER(19),
    comment_comment_id NUMBER(19),
    PRIMARY KEY (report_id)
);

CREATE TABLE cat_author (
    author_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    name VARCHAR2(50 CHAR) NOT NULL,
    PRIMARY KEY (author_id)
);

CREATE TABLE cat_book (
    book_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    title VARCHAR2(100 CHAR) NOT NULL,
    isbn VARCHAR2(13 CHAR),
    price NUMBER(10,2),
    rating BINARY_DOUBLE,
    author_author_id NUMBER(19),
    version NUMBER(19),
    last_modified_by VARCHAR2(50 CHAR),
    PRIMARY KEY (book_id)
);

CREATE TABLE cat_reading (
    reading_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    label VARCHAR2(40 CHAR),
    note CLOB,
    raw_text CLOB,
    payload JSON,
    read_count NUMBER(10),
    total_count NUMBER(19),
    big_count NUMBER(38,0),
    units NUMBER(10),
    ratio NUMBER(5,2),
    exact_value NUMBER(38,2),
    amount NUMBER(12,2),
    score BINARY_DOUBLE,
    weight BINARY_FLOAT,
    active NUMBER(1),
    read_date DATE,
    read_time DATE,
    local_at TIMESTAMP(6),
    measured_at TIMESTAMP(6) WITH TIME ZONE,
    image BLOB,
    PRIMARY KEY (reading_id)
);

CREATE TABLE cat_region_code (
    code VARCHAR2(10 CHAR) NOT NULL,
    name VARCHAR2(50 CHAR) NOT NULL,
    country VARCHAR2(2 CHAR),
    PRIMARY KEY (code)
);

CREATE TABLE cat_status_code (
    code VARCHAR2(10 CHAR) NOT NULL,
    name VARCHAR2(50 CHAR) NOT NULL,
    phase VARCHAR2(10 CHAR),
    PRIMARY KEY (code)
);

CREATE TABLE cat_supplier (
    supplier_id VARCHAR2(10 CHAR) NOT NULL,
    name VARCHAR2(50 CHAR) NOT NULL,
    PRIMARY KEY (supplier_id)
);

CREATE TABLE shop_category (
    created_by VARCHAR2(50 CHAR),
    create_date TIMESTAMP(6),
    last_modified_by VARCHAR2(50 CHAR),
    last_modified_date TIMESTAMP(6),
    cat_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    name VARCHAR2(100 CHAR) NOT NULL,
    description CLOB,
    sort_order NUMBER(10),
    active NUMBER(1),
    parent_category_cat_id NUMBER(19),
    PRIMARY KEY (cat_id)
);

CREATE TABLE shop_products (
    created_by VARCHAR2(50 CHAR),
    create_date TIMESTAMP(6),
    last_modified_by VARCHAR2(50 CHAR),
    last_modified_date TIMESTAMP(6),
    product_id VARCHAR2(36 CHAR) NOT NULL,
    name VARCHAR2(200 CHAR) NOT NULL,
    sku VARCHAR2(50 CHAR) NOT NULL,
    description CLOB,
    price NUMBER(12,2) NOT NULL,
    cost_price NUMBER(12,2),
    stock_quantity NUMBER(10),
    weight BINARY_FLOAT,
    rating BINARY_DOUBLE,
    active NUMBER(1),
    launch_date DATE,
    last_restocked TIMESTAMP(6),
    uuid VARCHAR2(36 CHAR),
    metadata CLOB,
    thumbnail VARCHAR2(500 CHAR),
    manual_content CLOB,
    tags VARCHAR2(255 CHAR),
    category_cat_id NUMBER(19),
    PRIMARY KEY (product_id)
);

CREATE TABLE shop_products_aud (
    rev NUMBER(10) NOT NULL,
    revtype NUMBER(3),
    product_id VARCHAR2(36 CHAR) NOT NULL,
    created_by VARCHAR2(50 CHAR),
    create_date TIMESTAMP(6),
    last_modified_by VARCHAR2(50 CHAR),
    last_modified_date TIMESTAMP(6),
    name VARCHAR2(200 CHAR),
    sku VARCHAR2(50 CHAR),
    description CLOB,
    price NUMBER(12,2),
    cost_price NUMBER(12,2),
    stock_quantity NUMBER(10),
    weight BINARY_FLOAT,
    rating BINARY_DOUBLE,
    active NUMBER(1),
    launch_date DATE,
    last_restocked TIMESTAMP(6),
    uuid VARCHAR2(36 CHAR),
    metadata CLOB,
    thumbnail VARCHAR2(500 CHAR),
    manual_content CLOB,
    tags VARCHAR2(255 CHAR),
    category_cat_id NUMBER(19),
    PRIMARY KEY (product_id, rev)
);

CREATE TABLE shop_customer (
    created_by VARCHAR2(50 CHAR),
    create_date TIMESTAMP(6),
    last_modified_by VARCHAR2(50 CHAR),
    last_modified_date TIMESTAMP(6),
    customer_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    first_name VARCHAR2(50 CHAR) NOT NULL,
    last_name VARCHAR2(50 CHAR) NOT NULL,
    email VARCHAR2(100 CHAR) NOT NULL,
    phone VARCHAR2(20 CHAR),
    date_of_birth DATE,
    loyalty_points NUMBER(19),
    customer_type VARCHAR2(1 CHAR),
    street VARCHAR2(200 CHAR),
    city VARCHAR2(100 CHAR),
    state VARCHAR2(50 CHAR),
    zip_code VARCHAR2(10 CHAR),
    country VARCHAR2(50 CHAR),
    vip_profile_profile_id NUMBER(19),
    PRIMARY KEY (customer_id)
);

CREATE TABLE shop_vip_profile (
    profile_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    tier VARCHAR2(20 CHAR),
    discount_rate BINARY_DOUBLE,
    enroll_date DATE,
    customer_customer_id NUMBER(19),
    PRIMARY KEY (profile_id)
);

CREATE TABLE shop_order (
    created_by VARCHAR2(50 CHAR),
    create_date TIMESTAMP(6),
    last_modified_by VARCHAR2(50 CHAR),
    last_modified_date TIMESTAMP(6),
    order_id VARCHAR2(36 CHAR) NOT NULL,
    order_date TIMESTAMP(6) NOT NULL,
    total_amount NUMBER(14,2),
    status VARCHAR2(3 CHAR),
    payment_method VARCHAR2(2 CHAR),
    customer_customer_id NUMBER(19),
    street VARCHAR2(200 CHAR),
    city VARCHAR2(100 CHAR),
    state VARCHAR2(50 CHAR),
    zip_code VARCHAR2(10 CHAR),
    country VARCHAR2(50 CHAR),
    notes CLOB,
    tracking_number VARCHAR2(50 CHAR),
    version NUMBER(19),
    PRIMARY KEY (order_id)
);

CREATE TABLE shop_order_aud (
    rev NUMBER(10) NOT NULL,
    revtype NUMBER(3),
    order_id VARCHAR2(36 CHAR) NOT NULL,
    created_by VARCHAR2(50 CHAR),
    create_date TIMESTAMP(6),
    last_modified_by VARCHAR2(50 CHAR),
    last_modified_date TIMESTAMP(6),
    order_date TIMESTAMP(6),
    total_amount NUMBER(14,2),
    status VARCHAR2(3 CHAR),
    payment_method VARCHAR2(2 CHAR),
    street VARCHAR2(200 CHAR),
    city VARCHAR2(100 CHAR),
    state VARCHAR2(50 CHAR),
    zip_code VARCHAR2(10 CHAR),
    country VARCHAR2(50 CHAR),
    notes CLOB,
    tracking_number VARCHAR2(50 CHAR),
    version NUMBER(19),
    customer_customer_id NUMBER(19),
    PRIMARY KEY (order_id, rev)
);

CREATE TABLE shop_order_item (
    order_item_id VARCHAR2(36 CHAR) NOT NULL,
    order_order_id VARCHAR2(36 CHAR),
    item_seq NUMBER(10),
    product_product_id VARCHAR2(36 CHAR),
    quantity NUMBER(10) NOT NULL,
    unit_price NUMBER(12,2) NOT NULL,
    discount NUMBER(8,2),
    PRIMARY KEY (order_item_id)
);

CREATE TABLE shop_shipment (
    shipment_id VARCHAR2(36 CHAR) NOT NULL,
    carrier VARCHAR2(30 CHAR),
    status VARCHAR2(3 CHAR),
    fee VARCHAR2(3 CHAR),
    sent_at TIMESTAMP(6) WITH TIME ZONE,
    cancelled_at TIMESTAMP(6),
    refunded_on DATE,
    PRIMARY KEY (shipment_id)
);

CREATE TABLE revinfo (
    rev NUMBER(10) NOT NULL,
    revtstmp NUMBER(19) NOT NULL,
    PRIMARY KEY (rev)
);

CREATE TABLE shop_outbox (
    id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    aggregate_type VARCHAR2(100 CHAR) NOT NULL,
    aggregate_id VARCHAR2(200 CHAR),
    event_type VARCHAR2(300 CHAR) NOT NULL,
    payload CLOB NOT NULL,
    occurred_on TIMESTAMP(6) WITH TIME ZONE,
    recorded_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    published_at TIMESTAMP(6) WITH TIME ZONE,
    attempts NUMBER(10) NOT NULL,
    last_error VARCHAR2(500 CHAR),
    PRIMARY KEY (id)
);

